import type { ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './receipt.module.scss'

export interface ReceiptLine {
  label: string
  qty?: number
  amount: number
  meta?: string
}

export interface ReceiptProps {
  title?: string
  subtitle?: string
  items: ReceiptLine[]
  subtotal?: number
  tax?: number
  tip?: number
  total: number
  currency?: string
  locale?: string
  footer?: ReactNode
  className?: string
}

/** Narrow, print-friendly receipt with a dashed rule and tabular figures. */
export function Receipt({
  title = 'Receipt',
  subtitle,
  items,
  subtotal,
  tax,
  tip,
  total,
  currency = 'USD',
  locale,
  footer,
  className,
}: ReceiptProps) {
  const format = (value: number) => {
    try {
      return new Intl.NumberFormat(locale, {
        style: 'currency',
        currency,
        maximumFractionDigits: 2,
      }).format(value)
    } catch {
      return `${currency} ${value.toFixed(2)}`
    }
  }

  return (
    <article className={cx(styles.root, className)}>
      <header className={styles.head}>
        <div>
          <h3 className={styles.title}>{title}</h3>
          {subtitle ? <p className={styles.subtitle}>{subtitle}</p> : null}
        </div>
        <span className={styles.meta}>{items.length} items</span>
      </header>

      <hr className={styles.rule} />

      <dl className={styles.items}>
        {items.map((item, index) => (
          <div key={`${item.label}-${index}`} className={styles.item}>
            <dt className={styles.itemLabel}>
              {item.label}
              {item.qty || item.meta ? (
                <span className={styles.itemMeta}>
                  {' '}
                  {item.qty ? `${item.qty} ×` : ''} {item.meta ?? ''}
                </span>
              ) : null}
            </dt>
            <dd className={styles.amount}>{format(item.amount)}</dd>
          </div>
        ))}
      </dl>

      <hr className={styles.rule} />

      <dl className={styles.totals}>
        {subtotal !== undefined ? (
          <div className={styles.totalRow}>
            <dt>Subtotal</dt>
            <dd className={styles.amount}>{format(subtotal)}</dd>
          </div>
        ) : null}
        {tax !== undefined ? (
          <div className={styles.totalRow}>
            <dt>Tax</dt>
            <dd className={styles.amount}>{format(tax)}</dd>
          </div>
        ) : null}
        {tip !== undefined ? (
          <div className={styles.totalRow}>
            <dt>Tip</dt>
            <dd className={styles.amount}>{format(tip)}</dd>
          </div>
        ) : null}
        <div className={cx(styles.totalRow, styles.grandTotal)}>
          <dt>Total</dt>
          <dd className={styles.amount}>{format(total)}</dd>
        </div>
      </dl>

      {footer ? <p className={styles.footer}>{footer}</p> : null}
    </article>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  width: 100%;
  max-width: 26rem;
  flex-direction: column;
  gap: vz.space(3);
  padding: vz.space(5);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('2xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(1);
  font-variant-numeric: tabular-nums;
}

.head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: vz.space(3);
}

.title {
  margin: 0;
  font-size: vz.font-size('lg');
  font-weight: 650;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 2px 0 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}

.meta {
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  text-align: right;
}

.rule {
  height: 1px;
  border: 0;
  background: repeating-linear-gradient(
    90deg,
    vz.color('border'),
    0 4px,
    transparent 4px 8px
  );
}

.items {
  display: flex;
  flex-direction: column;
  gap: vz.space(2);
  margin: 0;
}

.item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: vz.space(3);
}

.item-label {
  margin: 0;
  font-size: vz.font-size('sm');
}

.item-meta {
  display: block;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}

.amount {
  margin: 0;
  font-family: SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: vz.font-size('sm');
}

.totals {
  display: flex;
  flex-direction: column;
  gap: vz.space(1.5);
  margin: 0;
}

.total-row {
  display: flex;
  justify-content: space-between;
  gap: vz.space(3);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
}

.grand-total {
  padding-top: vz.space(2);
  border-top: 1px solid vz.color('border');
  color: vz.color('foreground');
  font-size: vz.font-size('base');
  font-weight: 700;
}

.footer {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.5;
  text-align: center;
}

@media print {
  .root {
    max-width: none;
    border: 0;
    box-shadow: none;
  }
}
